+++ b/include/ringbuf.h
@@ -26,6 +26,12 @@
 /* 取出最舊的值放到 *out；空的時回傳 false。 */
 bool rb_pop(RingBuf *rb, double *out);

+/* 把最舊的值放到 *out 但不取出，緩衝區是空的時回傳 false。 */
+bool rb_peek_oldest(const RingBuf *rb, double *out);
+
+/* 清空所有元素（容量不變，之後可以繼續放）。 */
+void rb_clear(RingBuf *rb);
+
 size_t rb_size(const RingBuf *rb);
 bool rb_is_full(const RingBuf *rb);


--- a/src/ringbuf.c
+++ b/src/ringbuf.c
@@ -40,6 +40,22 @@
     return true;
 }

+/* 把最舊的值放到 *out 但不取出，緩衝區是空的時回傳 false。 */
+bool rb_peek_oldest(const RingBuf *rb, double *out) {
+    if (rb->count == 0) {
+        return false;
+    }
+    size_t tail = (rb->head + rb->capacity - rb->count) % rb->capacity;
+    *out = rb->data[tail];
+    return true;
+}
+
+/* 清空所有元素（容量不變，之後可以繼續放）。 */
+void rb_clear(RingBuf *rb) {
+    rb->head = 0;
+    rb->count = 0;
+}
+
 size_t rb_size(const RingBuf *rb) { return rb->count; }

 bool rb_is_full(const RingBuf *rb) { return rb->count == rb->capacity; }

--- a/tests/test_ringbuf.cpp
+++ b/tests/test_ringbuf.cpp
@@ -41,3 +41,47 @@
     rb_push(&rb, 4.0);
     EXPECT_DOUBLE_EQ(rb_mean(&rb), 3.0);
 }
+
+TEST_F(RingBufTest, PeekOldest) {
+    double v = 0;
+    // Empty case
+    EXPECT_FALSE(rb_peek_oldest(&rb, &v));
+
+    // Single element
+    rb_push(&rb, 10.0);
+    EXPECT_TRUE(rb_peek_oldest(&rb, &v));
+    EXPECT_DOUBLE_EQ(v, 10.0);
+    // Ensure it didn't pop
+    EXPECT_EQ(rb_size(&rb), 1u);
+
+    // Multiple elements
+    rb_push(&rb, 20.0);
+    rb_push(&rb, 30.0);
+    EXPECT_TRUE(rb_peek_oldest(&rb, &v));
+    EXPECT_DOUBLE_EQ(v, 10.0);
+
+    // Overwrite case
+    rb_push(&rb, 40.0); // 10.0 is gone, oldest is 20.0
+    EXPECT_TRUE(rb_peek_oldest(&rb, &v));
+    EXPECT_DOUBLE_EQ(v, 20.0);
+}
+
+TEST_F(RingBufTest, Clear) {
+    rb_push(&rb, 1.0);
+    rb_push(&rb, 2.0);
+    rb_push(&rb, 3.0);
+    EXPECT_EQ(rb_size(&rb), 3u);
+
+    rb_clear(&rb);
+    EXPECT_EQ(rb_size(&rb), 0u);
+    
+    double v = 0;
+    EXPECT_FALSE(rb_pop(&rb, &v));
+    EXPECT_FALSE(rb_peek_oldest(&rb, &v));
+
+    // Ensure can still push after clear
+    rb_push(&rb, 5.0);
+    EXPECT_EQ(rb_size(&rb), 1u);
+    ASSERT_TRUE(rb_pop(&rb, &v));
+    EXPECT_DOUBLE_EQ(v, 5.0);
+}

